// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address owner, address recipient, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(recipient != address(0));
        vm.assume(owner != recipient);
        vm.assume(amount > 0 && amount <= type(uint96).max);

        c = new Phishable(owner);
        vm.deal(address(c), amount);

        uint256 recipientBalBefore = address(recipient).balance;
        uint256 msgSenderBalBefore = address(this).balance;

        vm.prank(owner);
        try c.withdrawAll(recipient) {
        } catch {
            assertTrue(true);
            return;
        }

        uint256 recipientBalAfter = address(recipient).balance;
        uint256 msgSenderBalAfter = address(this).balance;

        assertTrue(recipientBalAfter == recipientBalBefore + amount && msgSenderBalAfter == msgSenderBalBefore);
    }
}
